"type-size-slider": { markup: "<div class=\"sl-slider slider-type\" data-slider=\"type-size\" data-format=\"pixels\"   style=\"--low:0%;--high:37.5%;--position:37.5%;--fraction:0.375;--zoom:0.28;--preview-value:28px\"><div class=\"slider-header\"><label for=\"next-type-size\">Type size</label><output for=\"next-type-size\" data-output>28 px</output></div><div class=\"type-preview\" aria-hidden=\"true\"><span>Aa</span></div><div class=\"slider-track\"><span class=\"slider-rail\" aria-hidden=\"true\"><span class=\"slider-fill\"></span></span><input class=\"slider-input\" id=\"next-type-size\" name=\"type-size\" type=\"range\" min=\"16\" max=\"48\" step=\"1\" value=\"28\" ></div><div class=\"slider-ends\"><span>16 px</span><span>48 px</span></div></div>", css: style18, mount: api24.mount },
